-- ── story 3-3b: blocked locations ─────────────────────────────────────────
-- Generated by drizzle-kit (the four column statements) and hand-amended
-- around the generated part: the fail-fast guard, the pre-flight count, the
-- backfill and its post-check, the two CHECKs and the post-migration probe
-- (drizzle-kit is blind to CHECKs; `bun run db:generate` afterwards reports
-- "No schema changes").
--
-- A bin could already be blocked (`bins.blocked`, toggled by the PATCH since
-- story 1.3), but a block carried no reason, no who and no when. 3-3b adds
-- the block / unblock verbs (putaway's `BinStateCommand`), which record them:
--   * `blocked_reason text NULL` — one of `BIN_BLOCK_REASONS`
--     (src/shared/db/schema.ts), pinned TS ↔ DB by test/bin-block.spec.ts;
--   * `blocked_note text NULL` — 1–500 characters; required with `other`;
--   * `blocked_at timestamptz NULL`, `blocked_by uuid NULL` (no FK — guide §3).
-- `bins_blocked_pairing`: a blocked bin carries a reason (in the vocabulary —
-- `IS NOT NULL` before `IN`, guide §3) and a time, `other` carries a note, and
-- a blocker is set unless the row is a BACKFILLED one (reason `other` with
-- exactly the backfill note below); an active bin carries none of the four
-- (the unblock clears them all — the history lives on the audit rows).
--
-- And the short-pick reason vocabulary gains `skipped-blocked-bin`
-- (`SHORT_PICK_REASON_CODES`, pick.command.ts): the handheld's Skip of a
-- planned stop in a blocked bin (a zero-unit short that re-plans the stop).
-- `picklist_lines_reason_code_check` (0022) is dropped and re-added with the
-- widened set; every existing row satisfies it by construction (the set only
-- grows), so it is re-added NOT VALID — `picklist_lines` is ledger-sized.
--
-- `bins_blocked_pairing` is added NOT VALID too (design review A4): `bins`
-- grows with every warehouse grid and the migrator applies the whole pending
-- set in ONE transaction, so a VALID add would scan it under ACCESS
-- EXCLUSIVE. The backfill below writes every pre-existing blocked row into a
-- shape the CHECK admits, and the post-check PROVES every existing row
-- satisfies it (it raises when a blocked row lacks a reason or an active row
-- carries one). Both VALIDATEs run in a later migration (PENDING, deploy;
-- DEPLOY.md §5).
--
-- Additive: four nullable columns, no default — metadata-only, no rewrite.

-- ── 0. fail-fast ─────────────────────────────────────────────────────────
DO $$
BEGIN
	IF EXISTS (
		SELECT 1 FROM information_schema.columns
		 WHERE table_schema = 'public' AND table_name = 'bins' AND column_name = 'blocked_reason'
	) THEN
		RAISE EXCEPTION 'migration 0106: bins.blocked_reason already exists — this migration has already been applied.';
	END IF;
END $$;
--> statement-breakpoint
-- ── 1. pre-flight: how many bins the backfill will touch (the release note) ──
-- Every bin blocked before this deploy gets reason `other` with the backfill
-- note — the count is printed so the release note can say how many blocks an
-- operator should re-reason (unblock, then block with the real reason).
DO $$
DECLARE
	n bigint;
BEGIN
	SELECT count(*) INTO n FROM "bins" WHERE "blocked";
	RAISE NOTICE 'migration 0106: % bin(s) are blocked and will be backfilled with reason "other".', n;
END $$;
--> statement-breakpoint
ALTER TABLE "bins" ADD COLUMN "blocked_reason" text;--> statement-breakpoint
ALTER TABLE "bins" ADD COLUMN "blocked_note" text;--> statement-breakpoint
ALTER TABLE "bins" ADD COLUMN "blocked_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "bins" ADD COLUMN "blocked_by" uuid;--> statement-breakpoint
-- ── 2. the backfill (design review A5) ──────────────────────────────────
-- A guard first: nothing may already carry a reason (the columns are new, so
-- only a hand-edited database could) — a re-run must never overwrite one.
DO $$
BEGIN
	IF EXISTS (SELECT 1 FROM "bins" WHERE "blocked_reason" IS NOT NULL) THEN
		RAISE EXCEPTION 'migration 0106: a bin already carries a blocked_reason — refusing to backfill over it.';
	END IF;
END $$;
--> statement-breakpoint
-- `blocked_at` is the newest `bin.blocked` audit row of the bin: every toggle
-- (block AND unblock — the PATCH wrote one action for both) writes one, so
-- for a bin that is blocked NOW the newest row is the block. Ordered on
-- `created_at`, the server's commit stamp (guide §1). Falls back to
-- `updated_at` for a block older than the audit row (pre-3.6). The lookup
-- rides `audit_events_tenant_target_idx` (tenant, target_type, target_id).
-- `blocked_by` stays NULL: who blocked it before 3-3b is not reliably known,
-- and the CHECK admits a NULL blocker only on this exact backfilled shape.
UPDATE "bins" b
   SET "blocked_reason" = 'other',
       "blocked_note" = 'Blocked before story 3-3b recorded reasons',
       "blocked_at" = coalesce(
         (SELECT max(a."created_at")
            FROM "audit_events" a
           WHERE a."tenant_id" = b."tenant_id"
             AND a."target_type" = 'bin'
             AND a."target_id" = b."id"
             AND a."action" = 'bin.blocked'),
         b."updated_at")
 WHERE b."blocked";--> statement-breakpoint
-- The post-check: every existing row now satisfies the pairing — a blocked
-- row carries a reason and a time, an active row carries none of the four.
DO $$
DECLARE
	offenders text;
BEGIN
	SELECT string_agg(format('tenant %s bin %s (%s)', "tenant_id", "id", "code"), '; ' ORDER BY "tenant_id", "id")
	  INTO offenders
	  FROM "bins"
	 WHERE ("blocked" AND ("blocked_reason" IS NULL OR "blocked_at" IS NULL))
	    OR (NOT "blocked" AND ("blocked_reason" IS NOT NULL OR "blocked_note" IS NOT NULL OR "blocked_at" IS NOT NULL OR "blocked_by" IS NOT NULL));
	IF offenders IS NOT NULL THEN
		RAISE EXCEPTION 'migration 0106: the backfill left bins outside the blocked pairing: %', offenders;
	END IF;
END $$;
--> statement-breakpoint
-- ── hand-amended: the CHECKs (migration SQL only) ────────────────────────
ALTER TABLE "bins" ADD CONSTRAINT "bins_blocked_pairing" CHECK (
	("blocked"
		AND "blocked_reason" IS NOT NULL
		AND "blocked_reason" IN ('damaged','maintenance','contamination','temperature-excursion','safety-hazard','investigation','other')
		AND "blocked_at" IS NOT NULL
		AND ("blocked_reason" <> 'other' OR "blocked_note" IS NOT NULL)
		AND ("blocked_note" IS NULL OR char_length("blocked_note") BETWEEN 1 AND 500)
		AND ("blocked_by" IS NOT NULL
			OR ("blocked_reason" = 'other' AND "blocked_note" IS NOT NULL AND "blocked_note" = 'Blocked before story 3-3b recorded reasons')))
	OR (NOT "blocked"
		AND "blocked_reason" IS NULL
		AND "blocked_note" IS NULL
		AND "blocked_at" IS NULL
		AND "blocked_by" IS NULL)
) NOT VALID;--> statement-breakpoint
ALTER TABLE "picklist_lines" DROP CONSTRAINT "picklist_lines_reason_code_check";--> statement-breakpoint
ALTER TABLE "picklist_lines" ADD CONSTRAINT "picklist_lines_reason_code_check" CHECK (
	"reason_code" IS NULL
	OR (
		"status" IN ('short','cancelled')
		AND "reason_code" IN ('bin-empty','fewer-units-than-planned','damaged-units','stock-not-found','other','skipped-blocked-bin')
	)
) NOT VALID;--> statement-breakpoint
-- ── the post-migration assertion (the 0092 / 0094 model) ──────────────────
-- Made-up uuids. (a) Both CHECKs are present and NOT VALID. (b) The accepted
-- shapes are inserted first and rolled back by a sentinel exception, so a
-- CHECK that refused everything fails the migration. (c) Each refused shape
-- runs in its own subtransaction and must be refused BY ITS NAMED CONSTRAINT
-- (`bins_blocked_pairing` sorts before every other bins CHECK, and each
-- picklist probe row satisfies every CHECK named before the reason check).
DO $$
DECLARE
	t uuid := gen_random_uuid();
	w uuid := gen_random_uuid();
	z uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
	n int;
BEGIN
	-- (a)
	SELECT count(*) INTO n
	  FROM pg_constraint
	 WHERE contype = 'c'
	   AND NOT convalidated
	   AND ((conrelid = 'public.bins'::regclass AND conname = 'bins_blocked_pairing')
	     OR (conrelid = 'public.picklist_lines'::regclass AND conname = 'picklist_lines_reason_code_check'));
	IF n <> 2 THEN
		RAISE EXCEPTION 'migration 0106: expected bins_blocked_pairing and picklist_lines_reason_code_check present and NOT VALID, found % so.', n;
	END IF;
	-- (b) accepted shapes: an active bin; a blocked bin under every reason
	-- (with and without a note; `other` with one; a 500-character note); the
	-- backfilled shape (no blocker); a short line under the new reason and a
	-- legacy one.
	BEGIN
		INSERT INTO "bins" ("id","tenant_id","warehouse_id","zone_id","code","capacity","type","blocked","blocked_reason","blocked_note","blocked_at","blocked_by")
		VALUES
			(gen_random_uuid(), t, w, z, 'P-ACTIVE', 1000, 'shelf', false, NULL, NULL, NULL, NULL),
			(gen_random_uuid(), t, w, z, 'P-DAMAGED', 1000, 'shelf', true, 'damaged', NULL, now(), u),
			(gen_random_uuid(), t, w, z, 'P-MAINT', 1000, 'shelf', true, 'maintenance', 'racking bolt sheared', now(), u),
			(gen_random_uuid(), t, w, z, 'P-CONT', 1000, 'shelf', true, 'contamination', NULL, now(), u),
			(gen_random_uuid(), t, w, z, 'P-TEMP', 1000, 'shelf', true, 'temperature-excursion', NULL, now(), u),
			(gen_random_uuid(), t, w, z, 'P-SAFE', 1000, 'shelf', true, 'safety-hazard', NULL, now(), u),
			(gen_random_uuid(), t, w, z, 'P-INV', 1000, 'shelf', true, 'investigation', repeat('n', 500), now(), u),
			(gen_random_uuid(), t, w, z, 'P-OTHER', 1000, 'shelf', true, 'other', 'forklift parked across it', now(), u),
			(gen_random_uuid(), t, w, z, 'P-BACKFILL', 1000, 'shelf', true, 'other', 'Blocked before story 3-3b recorded reasons', now(), NULL);
		INSERT INTO "picklist_lines" ("id","tenant_id","picklist_id","wave_id","order_id","order_line_id","sku_id","bin_id","qty","shortfall_qty","slice_seq","walk_seq","status","reason_code")
		VALUES
			(gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 5000, 5000, 0, 0, 'short', 'skipped-blocked-bin'),
			(gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 5000, 2000, 0, 0, 'short', 'bin-empty');
		RAISE EXCEPTION USING ERRCODE = 'P0106', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR not_null_violation OR unique_violation THEN
			RAISE EXCEPTION 'migration 0106: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0106' THEN
			NULL;
	END;
	-- (c) refused shapes, each by its named CHECK.
	FOREACH probe IN ARRAY ARRAY[
		'blocked without a reason', 'blocked with an unknown reason', 'blocked without a time',
		'blocked without a blocker', 'other without a note', 'a note over 500', 'an empty note',
		'active with a reason', 'active with a note', 'active with a time and blocker',
		'an unknown short reason'
	] LOOP
		refused_by := NULL;
		expected := CASE WHEN probe = 'an unknown short reason' THEN 'picklist_lines_reason_code_check' ELSE 'bins_blocked_pairing' END;
		BEGIN
			CASE probe
				WHEN 'blocked without a reason' THEN
					INSERT INTO "bins" ("id","tenant_id","warehouse_id","zone_id","code","capacity","type","blocked","blocked_reason","blocked_at","blocked_by")
					VALUES (gen_random_uuid(), t, w, z, 'R-1', 1000, 'shelf', true, NULL, now(), u);
				WHEN 'blocked with an unknown reason' THEN
					INSERT INTO "bins" ("id","tenant_id","warehouse_id","zone_id","code","capacity","type","blocked","blocked_reason","blocked_at","blocked_by")
					VALUES (gen_random_uuid(), t, w, z, 'R-2', 1000, 'shelf', true, 'haunted', now(), u);
				WHEN 'blocked without a time' THEN
					INSERT INTO "bins" ("id","tenant_id","warehouse_id","zone_id","code","capacity","type","blocked","blocked_reason","blocked_at","blocked_by")
					VALUES (gen_random_uuid(), t, w, z, 'R-3', 1000, 'shelf', true, 'damaged', NULL, u);
				WHEN 'blocked without a blocker' THEN
					INSERT INTO "bins" ("id","tenant_id","warehouse_id","zone_id","code","capacity","type","blocked","blocked_reason","blocked_note","blocked_at","blocked_by")
					VALUES (gen_random_uuid(), t, w, z, 'R-4', 1000, 'shelf', true, 'other', 'not the backfill note', now(), NULL);
				WHEN 'other without a note' THEN
					INSERT INTO "bins" ("id","tenant_id","warehouse_id","zone_id","code","capacity","type","blocked","blocked_reason","blocked_note","blocked_at","blocked_by")
					VALUES (gen_random_uuid(), t, w, z, 'R-5', 1000, 'shelf', true, 'other', NULL, now(), u);
				WHEN 'a note over 500' THEN
					INSERT INTO "bins" ("id","tenant_id","warehouse_id","zone_id","code","capacity","type","blocked","blocked_reason","blocked_note","blocked_at","blocked_by")
					VALUES (gen_random_uuid(), t, w, z, 'R-6', 1000, 'shelf', true, 'damaged', repeat('n', 501), now(), u);
				WHEN 'an empty note' THEN
					INSERT INTO "bins" ("id","tenant_id","warehouse_id","zone_id","code","capacity","type","blocked","blocked_reason","blocked_note","blocked_at","blocked_by")
					VALUES (gen_random_uuid(), t, w, z, 'R-7', 1000, 'shelf', true, 'damaged', '', now(), u);
				WHEN 'active with a reason' THEN
					INSERT INTO "bins" ("id","tenant_id","warehouse_id","zone_id","code","capacity","type","blocked","blocked_reason")
					VALUES (gen_random_uuid(), t, w, z, 'R-8', 1000, 'shelf', false, 'damaged');
				WHEN 'active with a note' THEN
					INSERT INTO "bins" ("id","tenant_id","warehouse_id","zone_id","code","capacity","type","blocked","blocked_note")
					VALUES (gen_random_uuid(), t, w, z, 'R-9', 1000, 'shelf', false, 'stale note');
				WHEN 'active with a time and blocker' THEN
					INSERT INTO "bins" ("id","tenant_id","warehouse_id","zone_id","code","capacity","type","blocked","blocked_at","blocked_by")
					VALUES (gen_random_uuid(), t, w, z, 'R-10', 1000, 'shelf', false, now(), u);
				ELSE
					INSERT INTO "picklist_lines" ("id","tenant_id","picklist_id","wave_id","order_id","order_line_id","sku_id","bin_id","qty","shortfall_qty","slice_seq","walk_seq","status","reason_code")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 5000, 5000, 0, 0, 'short', 'bin-blocked');
			END CASE;
		EXCEPTION
			WHEN check_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0106: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "bins" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "picklist_lines" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0106: a probe row survived.';
	END IF;
END $$;
